const id={"nav.learn":"Belajar","nav.path":"Jalur Kompetensi","nav.projects":"Proyek","nav.reference":"Referensi","nav.about":"Tentang","nav.start":"Mulai belajar","hero.eyebrow":"Cara yang lebih jelas untuk belajar elektronika","hero.title":"Belajar elektronika.<br><em>Bangun keterampilan nyata.</em>","hero.lede":"Mulai dari dasar, lanjutkan melalui kompetensi praktis, dan ubah pemahaman menjadi sesuatu yang benar-benar bekerja.","hero.primary":"Jelajahi jalurnya <span>→</span>","hero.secondary":"Lihat perpustakaan belajar","proof.levels":"tingkat kompetensi","proof.direction":"arah yang jelas","proof.build":"hal untuk dibuat","intro.title":"Dari “apa ini?”<br>menjadi “saya membuatnya.”","intro.text":"Elektronika lebih mudah dipahami ketika setiap ide memiliki tujuan. Setiap pelajaran menghubungkan konsep dengan kompetensi, latihan, dan proyek berikutnya.","path.title":"Naik dengan percaya diri.","path.one.title":"Dasar Kelistrikan","path.one.text":"Tegangan, arus, resistansi, daya, dan bahasa rangkaian.","path.two.title":"Komponen & Rangkaian","path.two.text":"Baca simbol, pilih komponen, dan buat rangkaian sederhana bekerja.","path.three.title":"Ukur & Uji","path.three.text":"Gunakan multimeter, temukan kesalahan, dan percayai rangkaianmu.","path.four.title":"Analog & Digital","path.four.text":"Bentuk sinyal, kendalikan logika, dan pahami yang terjadi di antaranya."};const lang=location.pathname.startsWith('/id');if(lang){document.documentElement.lang='id';for(const[k,v]of Object.entries(id))document.querySelectorAll(`[data-i18n="${k}"]`).forEach(e=>e.innerHTML=v);document.querySelectorAll('.brand').forEach(e=>e.href='/id/');document.querySelector('link[rel=canonical]').href='https://ecschema.com/id/';document.title='ECSchema — Belajar Elektronika. Bangun Keterampilan Nyata.'}document.getElementById('langSwitch').onclick=()=>location.href=lang?'/en/':'/id/';
